ST.xhtml:p:
nPerfectKRType :=  g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.dPerfectKRType;
dSlowStartCutDis := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.dSlowStartCutDis;
nCutting_Frequency := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.nCutting_Frequency;
nCutting_Duty := UINT_TO_LREAL(g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.nCutting_Duty);
nSlowStartCutFrequency :=  DINT_TO_UINT(g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.nSlowStartFrequency);
dSlowStartCutDuty  :=  g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.dSlowStartDuty;
  CASE nPerfectKRType OF
    1:(*方式1：直接把PWM拉成0*)
      g_nPwmFreq := 0;
      g_nPwmDuty :=0;

    2:(*方式2：PWM缓降到另一个PWM*)
       dEndCutDis:=dSlowStartCutDis;
      IF dEndCutDis <0.0 THEN(**防止除零***)
        dEndCutDis:=0.1;
      END_IF;
      dCurrentPwmFreq:= UINT_TO_UDINT(nSlowStartCutFrequency);
      dCurrentPwmDuty:=  LREAL_TO_UDINT(dSlowStartCutDuty);
      dFinallyPwmFreq:= UINT_TO_UDINT(nCutting_Frequency);
      dFinallyPwmDuty:= LREAL_TO_UDINT(nCutting_Duty);

      g_dSlowStartGoneDist := g_dSlowStartGoneDist + g_fiXYCurrentSpeedBuff*0.001;(**速度乘以周期就是移动的距离**)  
      dSlope := UDINT_TO_LREAL(dFinallyPwmFreq) -  UDINT_TO_LREAL(dCurrentPwmFreq);     
      dSlope := dSlope / dEndCutDis;
      IF g_dSlowStartGoneDist < dEndCutDis THEN(*只有不为0的时候才输出*)  
          IF dSlope > 0.0 THEN       
            g_nPwmFreq   := LREAL_TO_UINT(UDINT_TO_LREAL(dCurrentPwmFreq)) + LREAL_TO_UINT((ABS(dSlope)*g_dSlowStartGoneDist));
          ELSE 
            g_nPwmFreq   := LREAL_TO_UINT(UDINT_TO_LREAL(dCurrentPwmFreq)) - LREAL_TO_UINT((ABS(dSlope)*g_dSlowStartGoneDist));
          END_IF;
      END_IF;

      dSlope := UDINT_TO_LREAL(dFinallyPwmDuty)-UDINT_TO_LREAL(dCurrentPwmDuty);
      dSlope := dSlope / dEndCutDis; 
      IF g_dSlowStartGoneDist < dEndCutDis THEN (*只有不为0的时候才输出*)  
          IF dSlope > 0.0 THEN 
            g_nPwmDuty   := (UDINT_TO_UINT(dCurrentPwmDuty) + LREAL_TO_UINT(ABS(dSlope)*g_dSlowStartGoneDist));  
          ELSE 
            g_nPwmDuty   := (UDINT_TO_UINT(dCurrentPwmDuty) - LREAL_TO_UINT(ABS(dSlope)*g_dSlowStartGoneDist)); 
          END_IF;
      END_IF;
      IF g_nPwmFreq > 20000 THEN
        g_nPwmFreq :=20000;
      END_IF;
      IF g_nPwmDuty > 100 THEN
        g_nPwmDuty :=100;
      END_IF;

      IF g_nPwmFreq < 0 THEN
        g_nPwmFreq :=0;
      END_IF;
      IF g_nPwmDuty < 0 THEN
        g_nPwmDuty :=0;
      END_IF;    

    3:(*方式3：PWM突变到另一个PWM*) 
      g_nPwmFreq   :=nSlowStartCutFrequency;
      g_nPwmDuty   :=LREAL_TO_UINT(dSlowStartCutDuty);
  END_CASE;
